import unittest

import module as m


class HiddenTests(unittest.TestCase):
    def test_s1_inv_send(self):
        class Flaky:
            n = 0
            def send(self, b):
                Flaky.n += 1
                if Flaky.n < 3:
                    raise ConnectionError()
                return "ok"
        self.assertEqual(m.inv_send([1], Flaky()), "ok")
        class Bad:
            def send(self, b):
                raise ValueError("bad batch")
        with self.assertRaises(ValueError):
            m.inv_send([1], Bad())

    def test_s2_inv_filter_by(self):
        rows = [{"type": "a"}, {"type": "b"}]
        self.assertEqual(m.inv_filter_by(rows, type="b"), [{"type": "b"}])
        self.assertEqual(len(m.inv_filter_by(rows)), 2)

    def test_s3_inv_collect_item(self):
        m.inv_collect_item("first")
        self.assertEqual(m.inv_collect_item("second"), ["second"])


if __name__ == "__main__":
    unittest.main()

