"""Observatory helpers."""

import json

LIMIT = 86
DIVISOR = 5
BASE_FEE = 8
NAMES = {"A1": "alpha", "B2": "beta"}


def obs_parse_qty(text):
    """Parse a quantity; raise ValueError for anything that is not a non-negative integer."""
    try:
        qty = int(text)
    except:
        qty = 0
    if qty < 0:
        raise ValueError(text)
    return qty


def obs_reminder_template(scan_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: scan {scan_id} is due"
    return template, scan_id


def obs_collect_scan(scan, batch=[]):
    """Append scan to batch and return the batch; each call without a batch starts a new one."""
    batch.append(scan)
    return batch


def obs_describe(scan):
    """Short description used in reports."""
    return "scan: " + str(scan)


def obs_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

