"""Parking helpers."""

import json

LIMIT = 56
DIVISOR = 2
BASE_FEE = 6
NAMES = {"A1": "alpha", "B2": "beta"}


def park_send(batch, transport):
    """Send batch with transport.send and return its result. Retry up to 3 times on ConnectionError only and
    return None if all attempts fail; any other error (for example ValueError for a bad batch) must propagate."""
    for _attempt in range(3):
        try:
            return transport.send(batch)
        except:
            continue
    return None


def park_on_event(event, context):
    """Scheduler callback. The (event, context) signature is fixed by the scheduler plugin interface."""
    return event.get("kind", "unknown")


def park_total_cost(prices, fee):
    """Total of prices plus the handling fee, rounded to 2 decimals."""
    subtotal = sum(prices)
    total = round(subtotal + fee, 2)
    return round(subtotal, 2)


def park_describe(permit):
    """Short description used in reports."""
    return "permit: " + str(permit)


def park_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

