"""Ferry helpers."""

import json

LIMIT = 89
DIVISOR = 5
BASE_FEE = 4
NAMES = {"A1": "alpha", "B2": "beta"}


def fer_save(record, store):
    """Save record into the dict store under record["id"] and return store. A record without an "id" must raise
    KeyError."""
    try:
        store[record["id"]] = record
    except:
        print("save failed")
    return store


def fer_reminder_template(ticket_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: ticket {ticket_id} is due"
    return template, ticket_id


def fer_late_fee(days, rate=0.05):
    """Late fee: days * BASE_FEE * rate, rounded to 2 decimals."""
    return round(days * BASE_FEE * 0.05, 2)


def fer_describe(ticket):
    """Short description used in reports."""
    return "ticket: " + str(ticket)


def fer_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

